import{_ as n,l,o as e,c as i,v as t,p as s,x as r,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"反转","description":"","frontmatter":{"title":"反转","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/short-term-reversal.md","filePath":"quant/short-term-reversal.md","lastUpdated":1789023840000}'),E={name:"quant/short-term-reversal.md"};function m(u,a,c,B,A,_){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="反转" tabindex="-1">反转 <a class="header-anchor" href="#反转" aria-label="Permalink to &quot;反转&quot;">​</a></h1><div class="epigraph"><p>股票在一个月尺度上存在收益反转：上月的赢家下月偏弱，输家偏强；这一效应与三到十二个月的动量不在同一条期限结构上。</p><footer>—— Jegadeesh, Evidence of Predictable Behavior of Security Returns, Journal of Finance, 1990</footer></div><p>截面预测沿持有期会换符号。大约一个月，过去的赢家倾向于输给输家，这是短期反转；三到十二个月则是<a href="/quant/momentum-wml">动量</a>；三到五年又出现 De Bondt 与 Thaler 1985 年的长期反转。本篇以一个月反转为主，兼写长期反转为何不能当成「同一个过度反应」的简单延长。机制上，短期反转更接近流动性供给与买卖价差反弹，而不是估值比的慢变量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若收益是公平博弈加不可预测的信息，滞后一个月的收益不应进入预测回归。Jegadeesh 在个股截面上看到显著为负的一阶自相关；Lehmann 1990 用周度赢家输家组合得到同类结果。与此同时，中间 horizon 的动量为正。任何单一「反应不足」或单一「过度反应」都无法同时解释一个月为负、六个月为正。必须把期限结构切开：短端像提供流动性的补偿（或微观结构偏差），中端像趋势，长端像估值修复。</p><p>另一个混淆是出价-要价反弹。用成交价计算收益时，上一次若在买价成交、下一次在卖价成交，测到的收益自带负相关，尤其在低价、宽价差股票上。反转策略的账面夏普若主要来自这些股票，就不是可交易的风险溢价。问题因此变成：过滤价差、换到中点收益或推迟成交之后，负号还在不在。</p><h3 id="短期反转与长期反转不是一回事" tabindex="-1">短期反转与长期反转不是一回事 <a class="header-anchor" href="#短期反转与长期反转不是一回事" aria-label="Permalink to &quot;短期反转与长期反转不是一回事&quot;">​</a></h3><p>De Bondt–Thaler 把过去三年的输家与赢家做成组合，发现输家在随后三年跑赢。那是极端过去收益、长形成期、长持有期，样本里输家含大量困境与反弹期权。一个月反转的换手是一年十二次，长期反转的换手接近年度价值策略。把两者都叫做「反转因子」再放进同一张多空表，会把流动性供给与深度价值混成一个 β。</p><p><span class="marginnote">动量文献跳过最近一个月，正是为了不把本篇的短期反转吃进 WML。若你的动量形成期包含 t−1 月，先检查一下是不是在用反转的负号对冲动量的正号，净效应被压扁。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一个月反转的标准排序：在 t 月末按 t 月的收益（或 t 月减去最后几天，以减弱微观结构）把股票分成十分位或 2×3（再交叉规模）。多空组合在 t+1 月持有。价值加权能减轻买卖价差反弹；等权则把反转放大到不可交易区。更干净的做法是用报价中点收益排序、用次日可执行价格成交，或直接剔除 Amihud 非流动性最高的一组——见<a href="/quant/liquidity-factor">流动性因子</a>。</p><p>周度版本按 Lehmann：每周按过去一周收益排序，持有一周。效应更强、成本更高。长期反转按过去 36–60 个月累计收益排序，跳过最近 12 个月以免与动量冲突，持有 12 个月或更长。</p> \\[R_{i,t+1}=a+b\\,R_{i,t}+\\gamma^\\top X_{it}+\\varepsilon_{i,t+1},\\qquad b\\lt 0 \\]<p>是个股层面的诊断；\\(X\\) 里通常放规模、B/M。组合层面看的是输家减赢家的平均收益与三因子 α。短期反转的 α 对 HML 不敏感，对规模很敏感：小盘贡献了大部分。</p><h3 id="作为流动性供给的可交易形式" tabindex="-1">作为流动性供给的可交易形式 <a class="header-anchor" href="#作为流动性供给的可交易形式" aria-label="Permalink to &quot;作为流动性供给的可交易形式&quot;">​</a></h3><p>Nagel 把短期反转收益与 VIX、融资条件联系起来：波动上升、中介资本紧张时，反转溢价升高——提供即时流动性更贵。Avramov、Chordia、Goyal 指出反转集中在低流动性、高换手的股票。工程上这意味着：策略的「信号」其实是谁在上月被动承受了订单流冲击。做市或统计套利账户会自然做多上月被砸的、做空上月被追的，但必须用库存与价差约束，而不是满仓十分位。</p>',16)),(e(),s(p,null,{default:r(()=>[d(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20HORIZON%5B%22%E5%BD%A2%E6%88%90%E6%9C%9F%22%5D%20--%3E%20ST%5B%22%E7%BA%A6%201%20%E4%B8%AA%E6%9C%88%EF%BC%9A%E5%8F%8D%E8%BD%AC%22%5D%0A%20%20HORIZON%20--%3E%20MOM%5B%223%E2%80%9312%20%E4%B8%AA%E6%9C%88%EF%BC%9A%E5%8A%A8%E9%87%8F%22%5D%0A%20%20HORIZON%20--%3E%20LT%5B%223%E2%80%935%20%E5%B9%B4%EF%BC%9A%E9%95%BF%E6%9C%9F%E5%8F%8D%E8%BD%AC%22%5D%0A%20%20ST%20--%3E%20LIQ%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BE%9B%E7%BB%99%20%2F%20%E4%BB%B7%E5%B7%AE%E5%8F%8D%E5%BC%B9%22%5D%0A%20%20MOM%20--%3E%20WML%5B%22WML%22%5D%0A%20%20LT%20--%3E%20VAL%5B%22%E4%BC%B0%E5%80%BC%E4%B8%8E%E5%9B%B0%E5%A2%83%E6%9C%9F%E6%9D%83%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>微观结构通道：成交价在买卖报价之间跳动，测量收益含负的 MA(1) 成分。即使真实有效中点是随机游走，成交价序列仍可预测。用中点或用开盘到开盘、并跳过隔夜，可以减弱这条通道，但不能把所有短期反转都解释掉。</p><p>库存与风险承受通道：做市商或高频做市在冲击后需要把库存逆转，价格暂时偏离，随后回归。上月的大涨往往伴随买入主动单堆积，随后的回归表现为反转。这条通道预测：反转在广度差、深度差、共同基金赎回之后更强。</p><p>长期反转通道不同：过度外推成长、忽略均值回归的盈利，使高过去长期收益的公司估值偏贵。它与 <a href="/quant/value-factors">B/M 价值</a> 高度重叠——过去大涨的公司 B/M 往往变低。控制价值之后，长期反转显著变弱；一个月反转则不然。</p><h3 id="隔夜与日内" tabindex="-1">隔夜与日内 <a class="header-anchor" href="#隔夜与日内" aria-label="Permalink to &quot;隔夜与日内&quot;">​</a></h3><p>近年文献把日收益拆成隔夜与日内。美股上隔夜偏正、日内偏负的分解，和短期反转的腿会纠缠：开盘跳空可能是上日订单流的延续或反转，取决于样本。复制时必须固定收益时间戳（收盘到收盘 vs 开盘到开盘），并处理停牌与涨跌停——A 股上后者会把「上月涨停后的次月」变成不可交易的假反转。</p><p><span class="marginnote">等权一个月反转的纸面夏普几乎总是不可交易的。报告这个数字却不报换手、价差与容量，等于把做市利润记成因子溢价。价值加权、可借券、排除最低流动性十分位之后，若溢价仍在，才适合与 SMB、流动性因子并列讨论。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>换手接近 100%/月，成本模型必须用有效价差而不是报价价差的一半。卖空输家（上月赢家）相对容易，做多上月输家则常碰上停牌、低价、新闻股。涨跌停使排序与成交脱节：信号用了不可成交的收盘价。</p><p>不要把反转写成动量的「加负号」。期限不同、样本内相关结构不同、与价值的重叠不同。也不要把配对交易、指数套利的日内回归直接引用 Jegadeesh 1990——那是个股月度截面。长期反转若已用 HML 解释，就不要在五因子之外再加一条高度共线的「长期输家」因子，除非正交化后仍有独立溢价。</p><p><span class="marginnote">真实出处：Jegadeesh, Journal of Finance, 1990；Lehmann, Quarterly Journal of Economics, 1990；长期反转 De Bondt &amp; Thaler, Journal of Finance, 1985。流动性供给叙事见 Nagel 等后续工作，不要标成 1990 年论文已有 VIX 回归。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>短期反转是约一个月（及周度）的负自相关；长期反转是 3–5 年，与价值重叠。</li><li>中间 3–12 个月是动量，构造动量时必须跳过最近一个月。</li><li>机制以价差反弹与流动性供给为主；等权纸面溢价不可直接当容量。</li><li>与 Amihud 非流动性、规模高度纠缠，过滤与加权会改变结论。</li><li>出处：Jegadeesh, Journal of Finance, 1990；周度见 Lehmann, 1990；长期见 De Bondt &amp; Thaler, 1985。</li></ul>',13))])}const T=n(E,[["render",m]]);export{q as __pageData,T as default};
